(()=>{
'use strict';
const bank=BankGateway.createLocalSession(),root=document.querySelector('#bank-app');
const routes={overview:'总览',spending:'收支与订阅',wealth:'理财',tasks:'任务与记录'};
const ui={route:'overview',tab:'products',month:'2026-10',category:'all',search:'',risk:'all',term:'all',liquidity:'all',min:'all',eligible:false,compare:[],notice:'',error:false,hidden:false,mode:'success',draw:null,taskFilter:'all',busy:false,cardTab:false};
const labels={income:'收入',housing:'居住',dining:'餐饮',shopping:'购物',transport:'交通',subscription:'订阅',other:'其他',transfer:'转账'};
const status={awaiting_confirmation:'待确认',invalidated:'确认已失效',cancelled:'已取消',unknown:'结果待核实',processing:'待到账',succeeded:'已完成',failed:'明确失败',paused:'已中断',success:'成功',received:'已记录',blocked:'已拦截'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>ui.hidden?'••••':new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:n%100?2:0}).format(n/100);
const date=t=>new Date(t).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'});
const icons={overview:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',spending:'M4 4h16v16H4z M8 8h8 M8 12h4 M8 16h8',wealth:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',tasks:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',shield:'M12 3l8 3v6c0 5-8 9-8 9S4 17 4 12V6z M8 12l3 3 5-6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14 M13 6l6 6-6 6',search:'M10 17a7 7 0 1 1 0-14 7 7 0 0 1 0 14z M15 15l6 6',close:'M6 6l12 12 M6 18L18 6',check:'M5 12l5 5L20 7',down:'M6 9l6 6 6-6',plus:'M12 5v14 M5 12h14'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.arrow}"/></svg>`;
const tag=(t,tone='')=>`<span class="tag ${tone}">${esc(t)}</span>`;
function button(t,action,cls='button',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${t}</button>`;}
function notify(text,error=false){ui.notice=text;ui.error=error;}
function doAction(fn){try{fn();}catch(e){notify(e.message,true);}render();}
function go(route,tab){if(ui.draw){close();}ui.route=route;if(tab)ui.tab=tab;ui.notice='';history.replaceState(null,'','#/'+route+(route==='wealth'?'/'+ui.tab:''));render();document.querySelector('.page-heading h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function sectionHead(k,title,description,action=''){return `<div class="section-head"><div><span class="eyebrow">${k}</span><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}
function metric(k,v,note='',cls=''){return `<div class="metric ${cls}"><span>${k}</span><strong>${v}</strong>${note?`<small>${note}</small>`:''}</div>`;}
function empty(title,desc,action=''){return `<div class="empty"><span class="empty-mark">${icon('search')}</span><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function prerequisite(kind){const s=bank.state;const missing=!s.consent[kind];return missing?`<div class="callout"><span>${icon('shield')}</span><div><b>${kind==='trade'?'交易权限尚未开启':kind==='subscriptions'?'订阅管理权限尚未开启':'查询权限尚未开启'}</b><p>你仍可浏览虚构样本。操作前请开启对应的本地模拟权限，写操作还会单独确认。</p></div>${button('设置权限','permissions','button small')}</div>`:'';}
// Six scene cards follow the supplied capability blueprint. Existing business pages stay unchanged.
const sceneCards=[
 {id:'transfer',title:'智能转账',icon:'arrow',capability:'按人名、手机号或备注转账；定时转账；拆分 AA 收款。',state:'前端模拟',tone:'positive',note:'已有虚构名册转账、确认验证、余额同步和回执；定时与 AA 尚未实现。',action:'transfer',cta:'打开模拟转账',details:['按人名、手机号或备注查找收款对象','定时转账','拆分 AA 收款'],boundary:'可按姓名或手机号选择虚构名册联系人，备注仅用于检索。转账、验证、余额和回执均为浏览器本地模拟；定时和 AA 未实现，不连接真实银行。'},
 {id:'bills',title:'账单分析',icon:'spending',capability:'消费分类统计、异常交易识别、月度／年度账单报告。',state:'部分演示',tone:'purple',note:'已有月度分类与筛选；异常识别、年度报告待接入。',action:'spending',cta:'打开账单分析',details:['消费分类统计','异常交易识别','月度／年度账单报告'],boundary:'已有本地账单的月份、分类、交易查询、明细和分类分析。未把固定样本包装成自动异常识别或完整年度报告。'},
 {id:'investment',title:'理财操作',icon:'wealth',capability:'产品推荐与对比、风险评估、一键申购／赎回。',state:'本地模拟',tone:'positive',note:'已有产品筛选、对比、档案核验及模拟申购／赎回。',action:'wealth',cta:'打开理财',details:['产品推荐与对比','风险评估','一键申购／赎回'],boundary:'现有产品、风险档案和申赎均为虚构沙箱。风险档案核验不是正式测评；敏感操作仍需确认和演示验证，“一键”不表示跳过安全步骤。'},
 {id:'cards',title:'卡片管理',icon:'shield',capability:'卡申请、额度调整、交易限制／解锁、卡片挂失。',state:'前端模拟',tone:'positive',note:'已有模拟申请、额度、交易限制／解锁、挂失与统一记录。',action:'cards',cta:'管理模拟银行卡',details:['卡申请','额度调整','交易限制／解锁','卡片挂失'],boundary:'提供虚构银行卡及本地操作回执。借记卡额度是单日转账上限；信用卡额度只是样本字段，不代表授信。模拟申请次日审核；挂失不可直接解锁。不连接真实银行或语嫣接口。'},
 {id:'subscriptions',title:'订阅／代扣管理',icon:'tasks',capability:'自动识别订阅扣费、续费提醒、一键取消订阅。',state:'部分演示',tone:'purple',note:'已有周期扣费核实与模拟取消；自动识别、提醒待接入。',action:'subscriptions',cta:'打开订阅管理',details:['自动识别订阅扣费','续费提醒','一键取消订阅'],boundary:'现有演示支持核实周期扣费、保留或确认取消，且不把节省计入当前余额。尚未实现自动识别、提醒发送；银行代扣终止与商户订阅取消仍需区分。'},
 {id:'cross',title:'跨场景联动',icon:'plus',capability:'检测“我爱人生日”，当月锁定 1000 元活期，生日前 2 天订购鲜花、蛋糕。',state:'待接入',tone:'warning',note:'保留生日场景蓝本；资金锁定与商户预订尚未接通。',action:null,cta:'查看场景说明',details:['识别“我爱人生日”的需求','当月锁定 1000 元活期','生日前 2 天订购鲜花、蛋糕'],boundary:'当前资金目标、预演和任务记录可用于设计联动方案，但未实现生日识别、自动锁资、定时执行或商户下单。不得将保存目标视为锁资或预订成功。'}
];
function scenarioCards(){return `<section class="scene-cards-area" aria-labelledby="scene-cards-title"><div class="scene-cards-heading"><div><span class="eyebrow">BANKING CAPABILITIES</span><h2 id="scene-cards-title">六个场景，一个清楚的入口。</h2><p>保留六类核心能力；卡片状态说明当前演示范围。</p></div><span class="scene-blueprint-label">六类场景 · 能力蓝本</span></div><div class="scene-cards-grid">${sceneCards.map((c,i)=>`<article class="scene-card" data-scene="${c.id}"><div class="scene-card-top"><span class="scene-card-icon">${icon(c.icon)}</span><span class="scene-card-number">0${i+1}</span>${tag(c.state,c.tone)}</div><h3>${c.title}</h3><p class="scene-card-capability">${c.capability}</p><p class="scene-card-note">${c.note}</p><div class="scene-card-actions">${c.action?button(c.cta+' '+icon('arrow'),c.action,'button secondary small'):button(c.cta+' '+icon('arrow'),'scene-info','button secondary small',`data-id="${c.id}"`)}${c.action?button('能力说明','scene-info','text-link',`data-id="${c.id}"`):''}</div></article>`).join('')}</div><div class="scene-extras"><div><b>已有增强功能</b><p>在六类场景之外继续保留，辅助比较、授权与核对。</p></div><div>${button('资金预演','preview','button secondary small')}${button('授权中心','permissions','button secondary small')}${button('决策回放','tasks','button secondary small')}</div></div></section>`;}
function overview(){const s=bank.state,summary=bank.summary(),inProgress=s.operations.filter(o=>['awaiting_confirmation','unknown','processing'].includes(o.status));return `<div class="overview-grid"><section class="card asset-hero"><div class="hero-label"><span>账户资产总额</span>${tag('CNY · 模拟账本','dark')}</div><div class="hero-amount">${fmt(bank.total())}</div><div class="hero-bottom"><div><small>可用资金</small><b>${fmt(s.available)}</b></div><div><small>持仓本金</small><b>${fmt(s.positions.reduce((a,p)=>a+p.amount,0))}</b></div>${button('查看持仓 '+icon('arrow'),'holdings','button light small')}</div><div class="orbit" aria-hidden="true"></div></section><section class="card goal-summary"><div class="card-kicker">NEXT ON YOUR CALENDAR</div><h2>给下一步，<br>留好余地。</h2><div class="inline-stat"><span>${s.goal.months} 个月后必要用款</span><b>${fmt(s.goal.need)}</b></div><div class="inline-stat"><span>独立应急金</span><b>${fmt(s.goal.emergency)}</b></div>${button('调整资金计划 '+icon('arrow'),'plan','text-link')}</section><section class="card overview-spend">${sectionHead('THIS MONTH','本月收支','2026 年 10 月 · 已记账样本',button('分析账单 '+icon('arrow'),'analyze-overview','text-link'))}<div class="metrics three">${metric('收入',fmt(summary.income),'本地账单汇总')}${metric('支出',fmt(summary.expense),'含订阅 '+fmt(16900))}${metric('结余',fmt(summary.net),'不代表未来固定结余','positive')}</div><div class="category-bars">${Object.entries(summary.categories).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k,v])=>`<div><span>${labels[k]}</span><div><i style="width:${v/summary.expense*100}%"></i></div><b>${fmt(v)}</b></div>`).join('')}</div></section><section class="card overview-action"><div class="card-kicker">A LITTLE MORE ROOM</div><h3>把选择看清楚。</h3><p>从可用资金中先预留必要用款和应急金，再比较期限与流动性。</p><div class="allocation-number"><span>当前可配置上限</span><b>${fmt(bank.capacity())}</b></div>${button('进入理财 '+icon('arrow'),'wealth','button primary')}<small>低风险不等于无风险 · 不展示虚构收益</small></section><section class="card overview-sub">${sectionHead('RECURRING PAYMENTS','订阅与周期扣费','先核实需要，再决定保留或取消。',button('管理订阅','subscriptions','text-link'))}<div class="sub-mini">${s.subscriptions.map(x=>`<button data-action="subdetail" data-id="${x.id}"><span class="service-logo ${x.id}">${x.name[0]}</span><span>${x.name}<small>${x.status==='cancelled'?'已取消续费':x.reviewed?'已核实':'待核实'}</small></span><b>${fmt(x.amount)}<small>/月</small></b>${icon('arrow')}</button>`).join('')}</div><div class="footnote">已确认减少的未来月支出 ${fmt(bank.monthlySaved())}，不增加当前余额。</div></section><section class="card overview-tasks">${sectionHead('YOUR NEXT ACTION','待办与任务',null,button('全部记录','tasks','text-link'))}${inProgress.length?inProgress.map(o=>`<button class="task-mini" data-action="opdetail" data-id="${o.id}"><span>${tag(status[o.status],o.status==='unknown'?'warning':'purple')}<b>${esc(o.name)}</b></span><span>${icon('arrow')}</span></button>`).join(''):`<div class="quiet-state">${icon('check')}<div><b>没有待确认操作</b><p>分析、比较产品不会自动执行金融操作。</p></div></div>`}<div class="task-controls">${button('查看授权','permissions','button secondary small')}${button('试试资金预演','preview','button secondary small')}</div></section></div>${scenarioCards()}`;}
function spending(){const s=bank.state,summary=bank.summary(ui.month),tx=s.transactions.filter(t=>t.date.startsWith(ui.month)&&(ui.category==='all'||t.category===ui.category)&&(!ui.search||[t.name,t.id,t.date].join(' ').toLowerCase().includes(ui.search.toLowerCase())));return `<div class="tabs" aria-label="收支与订阅视图"><button data-action="spending-tab" data-id="bills" class="${ui.tab==='subscriptions'?'':'active'}">账单分析</button><button data-action="spending-tab" data-id="subscriptions" class="${ui.tab==='subscriptions'?'active':''}">订阅管理 ${s.subscriptions.filter(x=>x.status==='active').length}</button></div>${ui.tab==='subscriptions'?`${prerequisite('subscriptions')}<section class="card">${sectionHead('SUBSCRIPTIONS','每一项扣费，都有去留。','线索只用于核实，不会因使用次数少自动取消。')}<div class="metrics three">${metric('生效月付',fmt(s.subscriptions.filter(x=>x.status==='active').reduce((a,x)=>a+x.amount,0)))}${metric('未来每月减少',fmt(bank.monthlySaved()),'取消不退还本月费用')}${metric('待核实',s.subscriptions.filter(x=>!x.reviewed).length+' 项','逐项查看使用与扣费依据')}</div><div class="subscription-list">${s.subscriptions.map(x=>`<article><span class="service-logo ${x.id}">${x.name[0]}</span><div class="sub-info"><h3>${x.name} ${tag(x.status==='cancelled'?'已取消续费':x.reviewed?'已核实 · 生效中':'待核实','')}</h3><p>${x.note}</p><small>${x.status==='cancelled'?'下次续费已停止（模拟）':'月付 · 下次模拟续费 11 月 3 日'}</small></div><div class="sub-price"><b>${fmt(x.amount)}<small>/月</small></b>${button('查看与核实','subdetail','button secondary small',`data-id="${x.id}"`)}</div></article>`).join('')}</div><div class="footnote">本月已记账的订阅费用仍保留在账单中。取消后，仅减少下月起的情景支出。</div></section>`:`${prerequisite('read')}<section class="card">${sectionHead('CASH FLOW','看见钱的去向。','账单和余额使用同一份本地账本。',button('生成分类分析','analyze','button secondary'))}<div class="metrics three">${metric('收入',fmt(summary.income))}${metric('支出',fmt(summary.expense))}${metric('结余',fmt(summary.net),'本月收入 − 本月支出','positive')}</div><div class="filters"><label>月份<select data-filter="month"><option value="2026-10" ${ui.month==='2026-10'?'selected':''}>2026 年 10 月</option><option value="2026-09" ${ui.month==='2026-09'?'selected':''}>2026 年 9 月</option></select></label><label>分类<select data-filter="category"><option value="all">全部分类</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${ui.category===k?'selected':''}>${v}</option>`).join('')}</select></label><form id="transaction-search"><label>搜索交易<div class="search-input"><input name="query" value="${esc(ui.search)}" placeholder="名称、日期或编号"><button aria-label="搜索交易">${icon('search')}</button></div></label></form>${button('重置','reset-transactions','text-link')}</div><div class="table-scroll"><table><thead><tr><th>交易与时间</th><th>分类</th><th>状态</th><th class="numeric">金额</th><th></th></tr></thead><tbody>${tx.map(t=>`<tr><td><b>${esc(t.name)}</b><small>${t.date}</small></td><td>${labels[t.category]}</td><td>${tag('已记账')}</td><td class="numeric ${t.amount>0?'amount-positive':''}">${t.amount>0?'+':'−'}${fmt(Math.abs(t.amount))}</td><td>${button('详情','txdetail','text-link',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table></div>${!tx.length?empty('没有符合条件的账单','调整月份、分类或关键词。',button('清除筛选','reset-transactions','button secondary')):''}<div class="footnote">共 ${tx.length} 条样本记录。标为“汇总”的条目不代表单笔交易，不推断真实异常。</div></section>`}`;}
function goalForm(){const s=bank.state;return `<form id="goal-form"><div class="field-grid"><label>规划总额（元）<input name="total" type="number" min="100" max="${s.available/100}" step="0.01" required value="${Math.min(s.goal.total,s.available)/100}"></label><label>届时必要用款（元）<input name="need" type="number" min="0" step="0.01" required value="${s.goal.need/100}"></label><label>独立应急金（元）<input name="emergency" type="number" min="0" step="0.01" required value="${s.goal.emergency/100}"></label><label>用款期限（月）<input name="months" type="number" min="1" max="36" step="1" required value="${s.goal.months}"></label></div><div class="form-bottom"><span>不重复计算必要用款与应急金。修改会使旧确认失效。</span><button class="button primary">保存资金目标</button></div></form>`;}
function profileBox(){const s=bank.state;return `<div class="profile-box"><span>${icon('shield')}</span><div><b>风险档案：${s.profile==='valid'?'有效 · 低风险':s.profile==='expired'?'已过期':'缺失'}</b><p>本地档案样本，不是用户自报偏好或正式风险测评。</p></div>${button('查看档案','profile','text-link')}</div>`;}
function wealth(){const s=bank.state;const tabs=[['products','产品与推荐'],['plan','资金计划'],['holdings','我的持仓']];return `<div class="tabs">${tabs.map(([k,v])=>`<button data-action="wealth-tab" data-id="${k}" class="${ui.tab===k?'active':''}">${v}</button>`).join('')}</div>${ui.tab==='plan'?`<div class="two-col"><section class="card">${sectionHead('YOUR PLAN','先留好要用的钱。','预算、必要用款与应急金在此统一管理。')}${goalForm()}<div class="division"></div><form id="budget-form"><label>每月预计支出预算（元）<div class="input-action"><input name="budget" type="number" min="100" step="0.01" value="${s.budget/100}" required><button class="button secondary">更新预算</button></div></label><p class="help">用于预演，不改变历史支出。未来订阅节省会单独计入，不在此重复扣减。</p></form></section><section class="card side-plan">${profileBox()}<div class="reserve-stack"><div><span>当前可用资金</span><b>${fmt(s.available)}</b></div><div><span>必要用款</span><b>− ${fmt(s.goal.need)}</b></div><div><span>独立应急金</span><b>− ${fmt(s.goal.emergency)}</b></div><div class="reserve-total"><span>当前可配置上限</span><b>${fmt(bank.capacity())}</b></div></div>${button('比较产品 '+icon('arrow'),'wealth','button primary full')}${button('保持流动性，保存计划','liquid','text-link full')}</section></div>`:ui.tab==='holdings'?holdings():products()}`;}
function products(){const s=bank.state;let products=bank.catalog.filter(p=>(ui.risk==='all'||p.risk===Number(ui.risk))&&(ui.term==='all'||p.term<=Number(ui.term))&&(ui.min==='all'||p.min<=Number(ui.min))&&(ui.liquidity==='all'||(ui.liquidity==='flex'?p.term===0:p.term>0))&&(!ui.eligible||bank.eligibility(p.id).eligible));const match=bank.catalog.filter(p=>bank.eligibility(p.id).eligible).length;return `${prerequisite('trade')}<div class="product-layout"><div class="product-main"><section class="card recommendation">${sectionHead('PRODUCT SELECTION','让选择，适合你的安排。','依据有效低风险档案、'+s.goal.months+' 个月用款期限与配置金额筛选，不按虚构收益排序。',button('修改目标','plan','text-link'))}${profileBox()}<div class="selection-strip"><div><small>可配置上限</small><b>${fmt(bank.capacity())}</b></div><form id="amount-form"><label>本次配置金额（元）<div class="input-action"><input name="amount" type="number" min="0" step="0.01" max="${bank.capacity()/100}" value="${s.amount/100}" required><button class="button secondary small">更新</button></div></label></form><div><small>匹配样本</small><b>${match}<small> / ${bank.catalog.length}</small></b></div></div><p class="help">目录全部为虚构样本。产品不保证收益；当前未接入真实利率、净值或正式适当性核验。</p></section><section class="card catalog-card"><div class="filters product-filters"><label>风险<select data-filter="risk"><option value="all">全部风险</option><option value="1" ${ui.risk==='1'?'selected':''}>低风险样本</option><option value="3" ${ui.risk==='3'?'selected':''}>中风险样本</option></select></label><label>最长期限<select data-filter="term"><option value="all">全部期限</option>${[0,3,6,12].map(n=>`<option value="${n}" ${ui.term===String(n)?'selected':''}>${n? n+' 个月以内':'无锁定期'}</option>`).join('')}</select></label><label>流动性<select data-filter="liquidity"><option value="all">全部类型</option><option value="flex" ${ui.liquidity==='flex'?'selected':''}>无锁定期</option><option value="fixed" ${ui.liquidity==='fixed'?'selected':''}>有锁定期</option></select></label><label>起购金额<select data-filter="min"><option value="all">全部门槛</option>${[[10000,'¥100 以内'],[100000,'¥1,000 以内'],[500000,'¥5,000 以内']].map(([n,t])=>`<option value="${n}" ${ui.min===String(n)?'selected':''}>${t}</option>`).join('')}</select></label><label class="checkbox-filter"><input type="checkbox" data-filter="eligible" ${ui.eligible?'checked':''}>只看匹配</label>${button('重置','reset-products','text-link')}</div><div class="product-list">${products.map(p=>productCard(p)).join('')}</div>${!products.length?empty('没有符合条件的样本','放宽筛选，或调整配置金额与用款条件。',button('重置筛选','reset-products','button secondary')):''}</section></div><aside class="card compare-panel"><div class="card-kicker">SIDE BY SIDE</div><h3>看清差异，再决定。</h3><p>对比期限、门槛、流动性与限制，不比较没有来源的收益。</p><div class="compare-chips">${ui.compare.length?ui.compare.map(id=>{const p=bank.catalog.find(p=>p.id===id);return `<div><span>${p.name}</span>${button(icon('close'),'remove-compare','icon-button',`data-id="${id}" aria-label="移出${p.name}对比"`)}</div>`}).join(''):'<div class="compare-placeholder">从产品列表加入 2–3 项进行并列比较。</div>'}</div>${button('查看对比（'+ui.compare.length+'）','compare','button secondary full')}${ui.compare.length<2?'<small>不足两项也可打开，面板会提示补齐。</small>':''}<div class="division"></div><h4>不配置，也是一种选择。</h4><p>保留可用资金，必要时再安排。不会发生申购。</p>${button('保留流动性','liquid','text-link')}<div class="footnote">当前方案：${s.selected==='NONE'?'保持流动性':bank.catalog.find(p=>p.id===s.selected).name} · V${s.version}</div></aside></div>`;}
function productCard(p){const s=bank.state,e=bank.eligibility(p.id),selected=p.id===s.selected;return `<article class="product-row ${selected?'selected':''}"><div class="product-top"><div><div class="product-tags">${tag(p.type)}${tag(e.kind,e.eligible?'positive':p.risk>1?'danger':'warning')}</div><h3>${p.name}</h3></div>${selected?tag('当前选择','purple'):''}</div><div class="product-facts"><div><small>风险</small><b>${p.risk===1?'低风险':'中风险 · 可亏损'}</b></div><div><small>锁定期</small><b>${p.term?p.term+' 个月':'无锁定'}</b></div><div><small>起点</small><b>${fmt(p.min)}</b></div><div><small>收益</small><b>未提供</b></div></div><p class="product-reason">${e.eligible?'匹配依据：风险上限、金额门槛和用款期限均满足；仍需核实完整负债与真实银行规则。':e.reasons.map(esc).join('；')}</p><div class="product-actions">${button('详情与规则','productdetail','text-link',`data-id="${p.id}"`)}${button(ui.compare.includes(p.id)?'移出对比':'加入对比',ui.compare.includes(p.id)?'remove-compare':'add-compare','button secondary small',`data-id="${p.id}"`)}${button(selected?'预演与审阅':'选择并预演',selected?'preview':'choose','button '+(e.eligible?'primary':'secondary')+' small',`data-id="${p.id}"`)}</div></article>`;}
function holdings(){const s=bank.state,positions=s.positions.filter(p=>p.amount>0);return `${prerequisite('trade')}<section class="card">${sectionHead('YOUR POSITIONS','安排过的资金，在这里。','申购、赎回与账户余额共用同一账本。赎回提交后不会立即到账。',button('查找产品','wealth','button secondary'))}<div class="metrics three">${metric('持仓本金',fmt(positions.reduce((a,p)=>a+p.amount,0)))}${metric('赎回处理中',fmt(positions.reduce((a,p)=>a+p.reserved,0)))}${metric('已实现收益','未提供','不模拟投资收益')}</div><div class="holdings-list">${positions.map(pos=>{const p=bank.catalog.find(p=>p.id===pos.productId),mature=s.day>=pos.maturesAt;return `<article><div><span class="eyebrow">${p.type}</span><h3>${p.name}</h3><p>${mature?'已满足样本持有期':date(pos.maturesAt)+' 到期 · 不支持提前赎回'} · ${pos.source==='期初模拟储蓄持仓'?'期初模拟持仓':esc(pos.source)}</p></div><div class="holding-amount"><b>${fmt(pos.amount)}</b><small>其中占用 ${fmt(pos.reserved)}</small></div><div>${button('持仓详情','positiondetail','text-link',`data-id="${pos.id}"`)}${button(mature?'发起赎回':'查看到期条件','redeem','button secondary small',`data-id="${pos.id}"`)}</div></article>`}).join('')}</div>${!positions.length?empty('暂无持仓','可以先比较产品，也可以继续保留流动性。',button('查看产品','wealth','button primary')):''}</section>`;}
function transferPanel(){const s=bank.state,q=(ui.contactQuery||'').toLowerCase(),contacts=s.contacts.filter(c=>[c.name,c.phone,c.note].join(' ').toLowerCase().includes(q)),card=s.cards.find(c=>c.id==='CARD-DEBIT');return `<p class="panel-intro">仅向虚构名册模拟转账，所有记录共用当前浏览器账本。定时转账、AA 和真实收款人核验尚未实现。</p>${prerequisite('trade')}<div class="profile-box"><div><b>付款卡：${esc(card.name)} · ${card.last4} · ${card.status==='active'?'正常':card.status==='locked'?'交易受限':'已挂失'}</b><p>余额 ${fmt(s.available)} · 单日剩余限额 ${fmt(Math.max(0,card.limit-(card.spentDay===s.day?card.spent:0)))}</p></div>${button('管理卡片','cards','text-link')}</div><form id="recipient-search"><label>检索虚构收款人（姓名、手机号或名册备注）<div class="input-action"><input name="query" value="${esc(ui.contactQuery||'')}" placeholder="例如：小王、13800000001"><button class="button secondary">查找</button></div></label></form>${contacts.length?`<form id="transfer-form"><label>付款借记卡<select name="payer">${s.cards.filter(c=>c.kind==='debit').map(c=>`<option value="${c.id}">${esc(c.name)} · ${c.last4} · ${c.status==='active'?'正常':c.status==='lost'?'已挂失':'交易受限'} · 日限额 ${fmt(c.limit)}</option>`).join('')}</select></label><div class="field-grid"><label>虚构收款人<select name="recipient" required>${contacts.map(c=>`<option value="${c.id}">${esc(c.name)} · ${c.phone} · ${esc(c.note)}</option>`).join('')}</select></label><label>转账金额（元）<input name="amount" type="number" min="0.01" step="0.01" max="${s.available/100}" value="800" required></label></div><p class="help">当前必要用款与应急预留共 ${fmt(s.goal.need+s.goal.emergency)}；转账会减少可配置资金，可能影响资金目标。转账累计含本次≤1000元为黄色确认，超过为红色验证。验证演示码246810；本地卡限额不等于小组后台硬限额。</p><button class="button primary full">核对并生成转账确认</button></form>`:empty('没有找到名册联系人','更换姓名或手机号。不能向未经核验的任意号码转账。')}<div class="form-bottom">${button('查看全部任务与记录','tasks','text-link')}</div>`;}
function cardsPanel(){const s=bank.state;return `<p class="panel-intro">以下均为虚构银行卡，余额属于同一模拟账户。借记卡限额影响模拟转账；信用卡额度仅作样本展示，不生成授信或余额。挂失不可直接解锁。</p>${prerequisite('cards')}<div class="sim-cards">${s.cards.map(c=>`<article class="sim-bank-card"><div class="section-head compact"><h3>${esc(c.name)}</h3>${tag(c.status==='active'?'正常':c.status==='locked'?'交易受限':'已挂失',c.status==='active'?'positive':c.status==='lost'?'danger':'warning')}</div><p class="sim-card-number">•••• •••• •••• ${c.last4}</p><div class="inline-stat"><span>${c.kind==='debit'?'单日转账上限':'模拟信用额度'}</span><b>${fmt(c.limit)}</b></div><div class="product-actions">${c.status==='active'?button('调整额度','card-limit','button secondary small',`data-id="${c.id}"`)+button('限制交易','card_lock','button secondary small',`data-id="${c.id}"`):c.status==='locked'?button('解锁交易','card_unlock','button secondary small',`data-id="${c.id}"`):'<p class="help">已挂失，停止交易。可申请新的模拟卡；不会恢复原卡。</p>'}${c.status!=='lost'?button('模拟挂失','card_loss','button danger small',`data-id="${c.id}"`):''}</div></article>`).join('')}</div><div class="form-bottom">${button('申请模拟借记卡','card_apply','button primary')}${button('查看卡管理任务与回执','tasks','text-link')}</div><p class="help">申请仅进入待审核，需推进一个模拟日后查询审核；不是真实开户。卡片变化不会凭空增加资金。</p>`;}
const opNames={subscription:'取消订阅',purchase:'模拟申购',redeem:'模拟赎回',transfer:'模拟转账',card_apply:'模拟卡申请',card_limit:'调整卡额度',card_lock:'限制交易',card_unlock:'解锁交易',card_loss:'模拟挂失'};
const nonMoney=o=>['card_apply','card_lock','card_unlock','card_loss'].includes(o.type);
const opValue=o=>nonMoney(o)?'不扣款':o.type==='card_limit'?'新额度 '+fmt(o.amount):fmt(o.amount)+(o.type==='subscription'?'/月':'');
function opImpact(o){return o.type==='transfer'?'可用余额与资产总额减少，账单新增支出；不连接银行':o.type==='card_apply'?'仅提交模拟申请，次日查询审核；不增加资金':o.type==='card_limit'?'修改卡片样本额度，不增加账户余额或可用授信':o.type==='card_lock'?'该卡停止模拟交易，不改变余额':o.type==='card_unlock'?'仅恢复受限卡交易，挂失卡不能解锁':o.type==='card_loss'?'该卡永久停止本演示中的交易，不改变余额':o.type==='subscription'?'取消未来续费；当前资金不变':o.type==='purchase'?'可用资金转为模拟持仓；总资产不变':'提交赎回并占用本金；不立即到账';}
function tasks(){const s=bank.state,ops=s.operations.filter(o=>ui.taskFilter==='all'||(ui.taskFilter==='pending'?['awaiting_confirmation','unknown','processing'].includes(o.status):o.status===ui.taskFilter));return `<div class="task-status-strip"><div>${tag(s.locked?'执行已锁定':s.active?'任务可执行':'任务已中断',s.locked?'danger':s.active?'positive':'warning')}<span>仅中断未执行步骤，不撤回已完成操作。</span></div>${button(s.active?'中断后续任务':'恢复任务',s.active?'pause':'resume','button secondary small')}</div><section class="card">${sectionHead('TASKS & RECEIPTS','每一次操作，都有来路。','分析 → 核实 → 方案 → 确认 → 工具结果。任何页面发起的操作统一显示在这里。')}<div class="filters"><label>任务状态<select data-filter="taskFilter">${[['all','全部记录'],['pending','待处理'],['succeeded','已完成'],['failed','明确失败'],['cancelled','已取消'],['invalidated','确认失效']].map(([k,v])=>`<option value="${k}" ${ui.taskFilter===k?'selected':''}>${v}</option>`).join('')}</select></label><span class="muted">业务日期 ${date(s.day)} · 当前方案 V${s.version}</span>${button('测试设置','settings','text-link')}</div>${ops.length?`<div class="operation-list">${ops.slice().reverse().map(o=>`<article><div class="op-heading"><div>${tag(status[o.status],o.status==='succeeded'?'positive':o.status==='unknown'?'warning':o.status==='failed'?'danger':'purple')}<h3>${o.type==='transfer'?'模拟转账 · ':o.type==='card_apply'?'模拟卡申请 · ':''}${o.name}</h3></div><b>${opValue(o)}</b></div><div class="op-meta"><span>${o.id} · V${o.version}</span><span>${date(o.createdAt)}</span></div><p>${operationDescription(o)}</p><div class="product-actions">${button('决策回放','opdetail','text-link',`data-id="${o.id}"`)}${o.status==='awaiting_confirmation'?button('继续确认','confirm-op','button primary small',`data-id="${o.id}"`)+button('取消未执行操作','cancel-op','button secondary small',`data-id="${o.id}"`):''}${o.status==='unknown'?button('查询未知回执','query-op','button secondary small',`data-id="${o.id}"`):''}${o.status==='processing'?button(o.type==='card_apply'?'查询开卡审核':'查询到账状态','settle-op','button secondary small',`data-id="${o.id}"`):''}${o.status==='failed'?button('检查后重新发起','retry-op','button secondary small',`data-id="${o.id}"`):''}</div></article>`).join('')}</div>`:empty('没有符合条件的操作','浏览和对比不会触发申购；取消确认窗口会留下取消记录。',button('查看产品','wealth','button secondary'))}<div class="division"></div><div class="section-head compact"><h3>查询与方案记录</h3>${button('查看全部事件','all-events','text-link')}</div><div class="event-preview">${s.events.slice(-4).reverse().map(e=>`<div><span class="event-dot"></span><b>${esc(e.tool)}</b><span>${esc(status[e.status]||e.status)}</span></div>`).join('')||'<p class="muted">尚未生成事件。从任何业务入口开始即可。</p>'}</div></section>`;}
function operationDescription(o){if(o.type==='card_apply'&&o.status==='processing')return '模拟申请已受理，尚未开卡；推进一个模拟日后查询审核。';if(o.status==='succeeded'&&(o.type==='transfer'||o.type.startsWith('card_')))return opImpact(o)+'。已生成本地回执。';if(o.status==='unknown')return '结果未知。账本未按成功更新，后续写操作被阻止。只能查询回执，不直接重试。';if(o.status==='processing')return '申请已受理，本金仍在持仓中占用。预计下一个模拟日可查询；需要手动推进模拟时钟后核对。';if(o.status==='succeeded')return o.type==='subscription'?'已取消下次续费；当前余额未增加。':o.type==='purchase'?'可用资金转入模拟持仓，资产总额未变化。':'本金已确认到账，持仓减少、可用资金增加。';if(o.status==='failed')return '模拟接口明确失败；该操作未改变资金。请核实条件后重新生成确认。';if(o.status==='invalidated')return '目标、权限、产品或账本状态已变化。原确认不再有效，需要重新审阅。';if(o.status==='cancelled')return '已取消未执行步骤，没有发送资金操作。';return '对象、金额与方案版本已绑定；敏感操作还需要本地演示校验。';}
function render(){const s=bank.state;history.replaceState(null,'','#/'+ui.route+(ui.route==='wealth'?'/'+ui.tab:''));root.innerHTML=`<aside class="sidebar"><a class="brand" href="#/overview" data-action="overview"><span class="brand-symbol">b<span>·</span></span><span>banking<small>YOUR MONEY, WITH INTENT.</small></span></a><div class="nav-label">PERSONAL SPACE</div><nav aria-label="主导航">${Object.entries(routes).map(([k,v],i)=>`<button data-action="${k}" class="nav-item ${ui.route===k?'active':''}" ${ui.route===k?'aria-current="page"':''}>${icon(k)}<span>${v}</span><small>0${i+1}</small></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('shield')}<b>每个决定，始终由你。</b><p>方案可以预演。<br>执行必须经过你的确认。</p>${button('授权与控制','permissions','text-link')}</div><div class="account"><span>涵</span><div>谢涵微<small>个人演示账户</small></div>${tag('DEMO')}</div></div></aside><main><header class="app-header"><div class="breadcrumb">个人工作台<span>/</span><b>${routes[ui.route]}</b></div><div class="header-tools">${button(icon('search'),'assistant','icon-button',`aria-label="打开自然语言助手" title="自然语言助手"`)}${button(icon('eye'),'privacy','icon-button',`aria-label="${ui.hidden?'显示':'隐藏'}金额" title="${ui.hidden?'显示':'隐藏'}金额"`)}${button(icon('shield')+'<span>授权中心</span>','permissions','header-permission','aria-label="授权中心" title="授权中心"')}${button('沙箱设置','settings','header-setting')}</div></header><div class="page"><div class="page-heading"><div><span class="eyebrow">${{overview:'IN PERSPECTIVE',spending:'MONEY IN MOTION',wealth:'BUILT AROUND YOUR PLANS',tasks:'A RECORD OF EVERY STEP'}[ui.route]}</span><h1 tabindex="-1">${{overview:'你的财务，有章可循。',spending:'知道每一笔，去向何处。',wealth:'为下一段生活，做好安排。',tasks:'过程透明，结果可查。'}[ui.route]}</h1></div><div class="mode-label"><i></i>本地模拟<span>${date(s.day)}</span></div></div>${bank.storageWarning?`<div class="notice error" role="alert">${esc(bank.storageWarning)}</div>`:''}${ui.notice?`<div role="status" class="notice ${ui.error?'error':''}"><div>${esc(ui.notice)}</div>${button(icon('close'),'dismiss','icon-button',`aria-label="关闭提示"`)}</div>`:''}${!s.active?`<div class="callout warning"><div><b>任务已中断</b><p>所有页面仍可浏览，写操作暂时停止。已完成业务保持原状。</p></div>${button('恢复任务','resume','button secondary small')}</div>`:''}${s.locked?`<div class="callout warning"><div><b>执行已安全锁定</b><p>连续失败或验证码错误已达到阈值。请先核对记录。</p></div>${button('查看控制','permissions','button secondary small')}</div>`:''}<div id="route-content">${ui.route==='overview'?overview():ui.route==='spending'?spending():ui.route==='wealth'?wealth():tasks()}</div>${ui.route==='wealth'&&ui.tab==='products'?`<div class="mobile-compare"><div><b>已加入 ${ui.compare.length} 项对比</b><small>对比不触发申购</small></div>${button('查看对比','compare','button primary small')}${button('保留流动性','liquid','text-link')}</div>`:''}<footer class="app-footer"><span>BANKING / MAKE ROOM FOR WHAT'S NEXT.</span><span>虚构数据 · 浏览器本地保存 · 未连接小组后台或真实银行</span></footer></div></main><dialog id="panel" class="panel" aria-labelledby="panel-title" aria-describedby="panel-error"><div class="panel-top"><span class="eyebrow" id="panel-kicker"></span><button class="icon-button" id="close-panel" aria-label="关闭面板">${icon('close')}</button></div><h2 id="panel-title"></h2><div id="panel-body"></div><div id="panel-error" role="alert"></div></dialog>`;bind();if(ui.draw)draw(ui.draw);}
function open(type,id){ui.draw={type,id};draw(ui.draw);}
function close(){if(ui.draw&&ui.draw.type==='confirm')bank.cancel(ui.draw.id);ui.draw=null;const d=document.querySelector('#panel');if(d.open)d.close();render();if(ui.focusReturn){const target=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===ui.focusReturn.action&&(el.dataset.id||'')===ui.focusReturn.id);target?.focus();}}
function comparison(){const selected=ui.compare.map(id=>bank.catalog.find(p=>p.id===id));if(selected.length<2)return empty('加入至少两个产品，才能比较','先从产品列表加入样本。对比不意味着适合申购。',button('返回产品列表','close-products','button secondary'));const fields=[['类型',p=>p.type],['风险',p=>p.risk===1?'低风险，不等于无风险':'中风险，本金可能损失'],['期限',p=>p.term?p.term+' 个月':'无锁定期'],['起点',p=>fmt(p.min)],['赎回条件',p=>p.liquidity],['费用',p=>p.fee],['收益',()=> '未提供，不作收益排序'],['判断',p=>{const e=bank.eligibility(p.id);return e.eligible?'匹配：风险、期限与金额满足':e.reasons.join('；');}]];return `<p class="help">目录：本地虚构 v2 · 2026-10-19。所有产品与规则均为演示样本。</p><div class="table-scroll compare-table"><table><thead><tr><th>比较项</th>${selected.map(p=>`<th>${p.name}${button('移出','remove-compare','text-link',`data-id="${p.id}"`)}</th>`).join('')}</tr></thead><tbody>${fields.map(([label,fn])=>`<tr><th>${label}</th>${selected.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>选择</th>${selected.map(p=>`<td>${button('选择并预演','choose','button secondary small',`data-id="${p.id}"`)}</td>`).join('')}</tr></tbody></table></div><div class="callout"><div><b>保持流动性</b><p>不申购，不锁定资金。保存目标后可以稍后再安排。</p></div>${button('保存此选择','liquid','button primary small')}</div>`;}
function preview(){const s=bank.state,p=s.selected==='NONE'?null:bank.catalog.find(p=>p.id===s.selected);let rows=[],problem='';try{rows=bank.projection({income:ui.scenarioIncome??2850000,expense:ui.scenarioExpense??s.budget});}catch(e){problem=e.message;}const max=rows.length?Math.max(...rows.flatMap(r=>[r.baseline,r.planned,r.required])):1,min=rows.length?Math.min(0,...rows.map(r=>r.planned)):0;const point=(r,k,i)=>`${30+560*i/(rows.length-1)},${180-145*(r[k]-min)/(max-min||1)}`;const graph=rows.length?`<div class="chart-key"><span><i class="key-base"></i>保持现状</span><span><i></i>所选方案</span><span><i class="key-required"></i>必要用款＋应急金</span></div><svg class="projection-chart" viewBox="0 0 620 220" role="img" aria-label="情景可用资金比较，精确金额见下方表格"><path d="M30 35H590M30 105H590M30 180H590" fill="none" stroke="#e1e6ef"/><polyline points="${rows.map((r,i)=>point(r,'baseline',i)).join(' ')}" stroke="#9aa7bc" stroke-width="2" fill="none" stroke-dasharray="4 5"/><polyline points="${rows.map((r,i)=>point(r,'planned',i)).join(' ')}" stroke="#6c64d4" stroke-width="3" fill="none"/><polyline points="${rows.map((r,i)=>point(r,'required',i)).join(' ')}" stroke="#b88b7d" stroke-width="1.5" fill="none" stroke-dasharray="3 6"/><text x="30" y="208" fill="#8894a7" font-size="11">当前</text><text x="545" y="208" fill="#8894a7" font-size="11">${s.goal.months} 个月</text></svg>`:'';return `<div class="preview-selection"><span>当前方案</span><b>${p?p.name:'保留流动性'}</b>${tag('V'+s.version,'purple')}</div><form id="preview-form"><div class="field-grid"><label>配置金额（元）<input name="amount" type="number" min="0" step="0.01" max="${bank.capacity()/100}" value="${s.amount/100}" ${p?'':'readonly'} required></label><label>假设每月收入（元）<input name="income" type="number" min="0" step="0.01" value="${(ui.scenarioIncome??2850000)/100}" required></label><label>方案每月支出预算（元）<input name="expense" type="number" min="0" step="0.01" value="${(ui.scenarioExpense??s.budget)/100}" required></label><label>用款期限<input readonly value="${s.goal.months} 个月 · 在资金计划中修改"></label></div><div class="form-bottom">${button('修改资金目标','plan','text-link')}<button class="button secondary">更新预演</button></div></form>${problem?`<div class="notice error">${esc(problem)}</div>`:graph}<div class="callout"><div><b>事实与假设分开</b><p>起点为当前可用资金 ${fmt(s.available)}；现状月支出 ${fmt(1286000)}。方案收入、预算为用户假设，已确认订阅节省 ${fmt(bank.monthlySaved())}/月从下月计入。当前配置先扣减可用资金；固定期样本假设到期主动赎回，次月恢复本金，不计收益或费用。现有持仓未假设自动到账。</p></div></div><details class="evidence"><summary>查看精确金额、缺口与限制</summary><p>所有金额是情景计算，不是银行预测。缺口是“必要用款＋应急金”减去方案可用资金的正值。真实收益、负债、其他支出、交易日和银行到账规则尚未核验。</p><div class="table-scroll"><table><thead><tr><th>月后</th><th>现状可用</th><th>方案可用</th><th>未恢复本金</th><th>预留缺口</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.month}</td><td>${fmt(r.baseline)}</td><td>${fmt(r.planned)}</td><td>${fmt(r.locked)}</td><td>${fmt(r.gap)}</td></tr>`).join('')}</tbody></table></div></details>${p?`<div class="product-reason">${bank.eligibility(p.id).eligible?'当前样本满足筛选规则，但不等于正式适当性审核通过。':bank.eligibility(p.id).reasons.map(esc).join('；')}</div><div class="form-bottom">${button('暂不配置，保留流动性','liquid','button secondary')}${button('审阅模拟申购','purchase','button primary')}</div>`:button('保存流动性计划','liquid','button primary full')}`;}
function draw(descriptor){const s=bank.state,{type,id}=descriptor,d=document.querySelector('#panel');if(!d)return;let title='',kicker='',body='';d.className='panel '+(['compare','preview','all-events','opdetail','cards'].includes(type)?'wide':'');
 if(type==='transfer'){title='转账，每一步都可核对。';kicker='SIMULATED TRANSFER';body=transferPanel();}
 else if(type==='cards'){title='管理你的模拟银行卡。';kicker='CARDS & CONTROLS';body=cardsPanel();}
 else if(type==='card-edit'){const c=s.cards.find(c=>c.id===id);title='调整 '+c.name+' 的额度';kicker='CARD LIMIT';body=`<p class="panel-intro">${esc(c.name)} · 尾号 ${c.last4}。${c.kind==='debit'?'额度限制本模拟借记卡的当日转账总额':'仅修改虚构信用卡额度字段，不产生授信或资金'}。</p><form id="card-limit-form" data-card="${c.id}"><label>新额度（元，100–50000）<input name="limit" type="number" min="100" max="50000" step="0.01" value="${c.limit/100}" required></label><p class="help">当前 ${fmt(c.limit)}；变更后不会增加账户余额。</p><button class="button primary full">审阅额度变更</button></form>`;}
 else if(type==='card-review'){const o=s.operations.find(o=>o.id===id);title='查询模拟开卡审核';kicker='APPLICATION REVIEW';body=s.day<o.reviewAfter?`<p class="panel-intro">申请已受理，最早 ${date(o.reviewAfter)} 可查询。尚未开卡。</p>${button('推进模拟时钟','settings','button secondary full')}`:`<form id="card-review-form" data-op="${id}"><label>模拟审核结果<select name="result"><option value="success">审核通过并生成模拟卡</option><option value="failed">审核拒绝</option></select></label><p class="help">仅控制本地演示，不代表真实开户审批。</p><button class="button primary full">查询审核结果</button></form>`;}
 else if(type==='scene-info'){const c=sceneCards.find(x=>x.id===id);if(!c)throw Error('场景不存在');title=c.title;kicker='SCENE CAPABILITIES';body=`<div class="scene-info-body">${tag(c.state,c.tone)}<h3>蓝本中的典型能力</h3><ul>${c.details.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="callout"><div><b>当前实现范围</b><p>${c.boundary}</p></div></div>${c.action?button(c.cta,c.action,'button primary full'):button('返回场景卡片','close','button secondary full')}</div>`;}
 else if(type==='permissions'){title='授权，按需要开启。';kicker='AUTHORIZATION';body=`<p class="panel-intro">仅控制同一浏览器中的前端模拟引擎。所有产品与账户均虚构，不访问真实银行。授权不替代每笔操作确认。</p><form id="permission-form"><label class="permission-option"><input name="read" type="checkbox" ${s.consent.read?'checked':''}><div>${tag('查询 · 绿色','positive')}<b>读取与分析模拟数据</b><p>账单、订阅与风险档案；授权后查询无需重复确认。</p></div></label><label class="permission-option"><input name="subscriptions" type="checkbox" ${s.consent.subscriptions?'checked':''}><div>${tag('确认 · 黄色','warning')}<b>管理订阅</b><p>允许生成取消方案；执行前必须确认具体订阅与费用。</p></div></label><label class="permission-option"><input name="trade" type="checkbox" ${s.consent.trade?'checked':''}><div>${tag('交易 · 按级确认','purple')}<b>模拟转账、申购与赎回</b><p>转账当日累计不超过1000元需确认，超过需演示验证；申购和赎回需验证。</p></div></label><label class="permission-option"><input name="cards" type="checkbox" ${s.consent.cards?'checked':''}><div>${tag('验证 · 卡管理','danger')}<b>模拟卡片管理（仅本地扩展）</b><p>申请、额度、限制与挂失均需具体确认；不连接真实银行。</p></div></label><div class="panel-facts"><span>有效期：${s.consentExpiresAt?new Date(s.consentExpiresAt).toLocaleString('zh-CN'):'尚未授权'}；刷新保留，24 小时后需重新授权</span><span>交易可配置上限：${fmt(bank.capacity())}</span><span>状态：${s.locked?'执行锁定':s.active?'可执行':'任务中断'}</span></div><div class="form-bottom">${button('撤销全部授权','revoke','button secondary')}<button class="button primary">保存权限设置</button></div></form>${s.locked?`<div class="callout warning"><div><b>本地执行锁已触发</b><p>请先核对未知结果；重置执行锁不会清空账本或记录。</p></div>${button('核实并重置执行锁','unlock','button secondary small')}</div>`:''}`;}
 else if(type==='settings'){title='沙箱测试设置';kicker='LOCAL SANDBOX';body=`<p class="panel-intro">下面只改变本地演示环境。生产系统不能让用户指定交易结果或推进银行时间。</p><form id="settings-form"><label>新操作的模拟接口返回<select name="mode">${[['success','明确成功'],['failed','明确失败'],['unknown','结果未知']].map(([k,v])=>`<option value="${k}" ${ui.mode===k?'selected':''}>${v}</option>`).join('')}</select></label><label>风险档案测试样本<select name="profile">${[['valid','有效 · 低风险'],['expired','过期 · 低风险'],['missing','档案缺失']].map(([k,v])=>`<option value="${k}" ${s.profile===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button primary full">保存测试设置</button></form><div class="division"></div><form id="clock-form"><label>模拟业务时钟 · ${date(s.day)}<select name="days">${[1,30,90,180,360].map(n=>`<option value="${n}">推进 ${n} 天</option>`).join('')}</select></label><p class="help">只改变业务日期。资金不会自动到账，仍需在任务中查询结果。</p><button class="button secondary full">推进模拟时钟</button></form><div class="division"></div>${button('刷新并保留整场演示','reset-dialog','button secondary full')}${button('下载模拟记录备份','export-demo','text-link full')}<p class="help">刷新保留同一浏览器中的账本、银行卡和任务；不恢复初始资金。无痕模式、清除站点数据、更换浏览器或文件路径可能无法恢复。不会同步到其他设备。</p>`;}
 else if(type==='profile'){title='风险档案';kicker='RISK PROFILE';body=`${tag(s.profile==='valid'?'有效 · 低风险':s.profile==='expired'?'已过期':'档案缺失',s.profile==='valid'?'positive':'warning')}<dl class="fact-list"><div><dt>来源</dt><dd>本地模拟风险档案 v2</dd></div><div><dt>有效状态</dt><dd>${s.profile==='valid'?'仅演示有效状态':'不允许新申购'}</dd></div><div><dt>风险上限</dt><dd>低风险样本；不等于无风险</dd></div><div><dt>仍需核验</dt><dd>正式测评、完整资产负债、真实产品适当性</dd></div></dl><p class="help">这里不能通过自报偏好提高风险等级。异常分支可在明确标注的沙箱设置中切换。</p>${button('打开沙箱测试设置','settings','button secondary full')}`;}
 else if(type==='txdetail'){const t=s.transactions.find(t=>t.id===id);title='交易详情';kicker='TRANSACTION';body=`<div class="detail-amount">${t.amount<0?'−':'+'}${fmt(Math.abs(t.amount))}</div><dl class="fact-list"><div><dt>名称</dt><dd>${esc(t.name)}</dd></div><div><dt>分类</dt><dd>${labels[t.category]}</dd></div><div><dt>记账时间</dt><dd>${t.date}</dd></div><div><dt>记录编号</dt><dd>${t.id}</dd></div><div><dt>数据来源</dt><dd>${t.source}</dd></div></dl><p class="help">${t.note}</p>${t.category==='subscription'?button('管理周期扣费','subscriptions','button primary full'):''}`;}
 else if(type==='analysis'){const a=bank.summary(ui.month);title=ui.month+' 收支分析';kicker='TRANSACTIONS.ANALYZE';body=`<div class="metrics three">${metric('收入',fmt(a.income))}${metric('支出',fmt(a.expense))}${metric('结余',fmt(a.net))}</div><div class="category-bars">${Object.entries(a.categories).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div><span>${labels[k]}</span><div><i style="width:${v/a.expense*100}%"></i></div><b>${fmt(v)}</b></div>`).join('')}</div><p class="help">依据当前月份本地已记账记录汇总；订阅已经包含在总支出中。未生成缺乏依据的异常交易判断。</p>${button('继续核实订阅','subscriptions','button primary full')}`;}
 else if(type==='subdetail'){const x=s.subscriptions.find(x=>x.id===id);title=x.name;kicker='RECURRING PAYMENT';body=`<div class="detail-amount">${fmt(x.amount)}<small>/月</small></div>${tag(x.status==='cancelled'?'已取消续费':x.reviewed?'已核实':'待核实',x.status==='cancelled'?'positive':'')}<dl class="fact-list"><div><dt>扣费依据</dt><dd>2026-09 与 2026-10 各有一笔同名等额扣费（虚构样本）</dd></div><div><dt>使用情况</dt><dd>${x.usage}</dd></div><div><dt>待判断线索</dt><dd>${x.note}</dd></div><div><dt>取消影响</dt><dd>下月起不再续费，不退当期费用，不增加余额</dd></div><div><dt>数据来源</dt><dd>本地订阅与使用记录 v2</dd></div></dl>${prerequisite('read')}${prerequisite('subscriptions')}<div class="form-bottom">${x.status!=='cancelled'?button('核实并保留','keep-sub','button secondary',`data-id="${id}"`)+button('核实并审阅取消','cancel-sub','button danger',`data-id="${id}"`):button('查看相关回执','sub-receipts','button secondary full',`data-id="${id}"`)}</div>`;}
 else if(type==='productdetail'){const p=bank.catalog.find(p=>p.id===id),e=bank.eligibility(id);title=p.name;kicker='PRODUCT DETAILS';body=`<div class="product-tags">${tag(p.type)}${tag(e.kind,e.eligible?'positive':'warning')}</div><p class="panel-intro">${p.description}</p><dl class="fact-list"><div><dt>风险</dt><dd>${p.risk===1?'低风险；不等于无风险':'中风险；本金可能损失'}</dd></div><div><dt>最低金额</dt><dd>${fmt(p.min)}</dd></div><div><dt>期限</dt><dd>${p.term?p.term+' 个模拟月':'无锁定期'}</dd></div><div><dt>申赎规则</dt><dd>${p.liquidity}</dd></div><div><dt>费用</dt><dd>${p.fee}</dd></div><div><dt>收益、利率与净值</dt><dd>未提供，不填入假设收益</dd></div><div><dt>来源与更新时间</dt><dd>${p.source} / ${p.updated}</dd></div></dl><div class="callout"><div><b>筛选依据</b><p>${e.eligible?'当前风险、期限、金额门槛符合本地规则；仍需真实适当性核验。':e.reasons.map(esc).join('；')}</p></div></div><div class="form-bottom">${button(ui.compare.includes(id)?'移出对比':'加入对比',ui.compare.includes(id)?'remove-compare':'add-compare','button secondary',`data-id="${id}"`)}${button('选择并预演','choose','button primary',`data-id="${id}"`)}</div>`;}
 else if(type==='compare'){title='把不同选择，放在一起。';kicker='PRODUCT COMPARISON';body=comparison();}
 else if(type==='preview'){title='决定之前，先看影响。';kicker='FINANCIAL TIME MACHINE';body=preview();}
 else if(type==='positiondetail'||type==='redeem'){const pos=s.positions.find(p=>p.id===id),p=bank.catalog.find(p=>p.id===pos.productId),mature=s.day>=pos.maturesAt;title=type==='redeem'?'发起模拟赎回':p.name+' · 持仓';kicker='YOUR POSITION';body=`<div class="detail-amount">${fmt(pos.amount)}</div><dl class="fact-list"><div><dt>持仓编号</dt><dd>${pos.id}</dd></div><div><dt>来源</dt><dd>${esc(pos.source)}</dd></div><div><dt>未占用可赎回本金</dt><dd>${fmt(pos.amount-pos.reserved)}</dd></div><div><dt>样本到期日</dt><dd>${date(pos.maturesAt)} · ${mature?'已满足期限':'未到期'}</dd></div><div><dt>赎回规则</dt><dd>${p.liquidity}</dd></div></dl>${!mature?`<div class="callout warning"><div><b>尚未到期</b><p>该样本不支持提前赎回。可以继续查看持仓；测试到期分支需明确推进模拟时钟。</p></div></div>${button('查看模拟时钟设置','settings','button secondary full')}`:`<form id="redeem-form" data-position="${id}"><label>赎回金额（元）<input name="amount" type="number" min="0.01" step="0.01" max="${(pos.amount-pos.reserved)/100}" value="${(pos.amount-pos.reserved)/100}" required></label><p class="help">申请受理后资金仍在持仓中占用；下一个模拟日查询成功才入账。不会立即增加可用余额。</p><button class="button primary full">生成赎回确认</button></form>`}`;}
 else if(type==='confirm'){const o=s.operations.find(o=>o.id===id);title='审阅'+(opNames[o.type]||'模拟操作');kicker='YOUR CONFIRMATION';body=`<div class="product-tags">${tag(o.level==='red'?'红色操作 · 需要演示验证':'黄色操作 · 需要明确确认',o.level==='red'?'danger':'warning')}${tag('V'+o.version)}</div><dl class="fact-list"><div><dt>对象</dt><dd>${o.name}</dd></div>${o.type==='transfer'?`<div><dt>付款卡</dt><dd>${esc(s.cards.find(c=>c.id===o.cardId)?.name||'模拟卡')} · ${s.cards.find(c=>c.id===o.cardId)?.last4||''}</dd></div>`:''}<div><dt>金额</dt><dd>${opValue(o)}</dd></div><div><dt>操作编号</dt><dd>${o.id}</dd></div><div><dt>确认有效期</dt><dd>预览300秒；红色验证120秒。时间过期需重新审阅。</dd></div><div><dt>具体影响</dt><dd>${opImpact(o)}</dd></div><div><dt>测试接口分支</dt><dd>${ui.mode==='success'?'明确成功':ui.mode==='failed'?'明确失败':'结果未知'} · 可在沙箱设置调整</dd></div></dl><form id="confirm-form" data-op="${id}">${o.level==='red'?`<label>本地演示校验码<input name="code" inputmode="numeric" maxlength="6" placeholder="输入演示码 246810" autocomplete="off" required></label><p class="help">演示码 246810 只验证本地交互，不是真实身份验证或生产 MFA。</p>`:''}<label class="checkline"><input name="confirm" type="checkbox" required>我已核对对象、金额与影响，同意本次模拟操作。</label><div class="form-bottom">${button('返回调整','close','button secondary')}<button class="button primary">确认${opNames[o.type]||'模拟操作'}</button></div></form>`;}
 else if(type==='opdetail'||type==='all-events'){const o=type==='opdetail'?s.operations.find(o=>o.id===id):null;title=o?'操作回执与决策回放':'完整任务事件';kicker='DECISION REPLAY';const events=o?s.events.filter(e=>e.opId===o.id||e.version===o.version&&['goal.update','allocation.update','consent.update','profile.fixture','budget.update'].includes(e.tool)):s.events;body=`${o?`<div class="receipt-head">${tag(status[o.status],o.status==='succeeded'?'positive':o.status==='failed'?'danger':'warning')}<b>${o.name}</b><strong>${opValue(o)}</strong></div><p class="panel-intro">${operationDescription(o)}</p><dl class="fact-list"><div><dt>操作 / 版本</dt><dd>${o.id} / V${o.version}</dd></div><div><dt>创建 / 提交</dt><dd>${date(o.createdAt)} / ${o.submittedAt?date(o.submittedAt):'未提交'}</dd></div><div><dt>数据来源</dt><dd>本地账本、产品目录与风险档案 v2</dd></div></dl><details class="evidence"><summary>查看创建时的输入、规则与依赖快照</summary><p>操作基于 V${o.version}：当时可用 ${fmt(o.snapshot.available)}，目标 ${fmt(o.snapshot.goal.total)}，必要用款 ${fmt(o.snapshot.goal.need)}，应急金 ${fmt(o.snapshot.goal.emergency)}，${o.snapshot.goal.months} 个月。风险档案 ${o.snapshot.profile==='valid'?'有效 · 低风险':o.snapshot.profile==='expired'?'过期':'缺失'}；目录 ${o.snapshot.catalog}。</p>${o.cardSnapshot?`<p>卡片快照：${esc(o.cardSnapshot.name)} · ${o.cardSnapshot.last4}，状态 ${o.cardSnapshot.status}，原额度 ${fmt(o.cardSnapshot.limit)}。不产生资金或授信。</p>`:''}${o.cardId?`<p>付款卡编号：${esc(o.cardId)}；执行仍受当前卡状态与累计限额约束。</p>`:''}<p>依赖顺序：${o.dependencies.map(esc).join(' → ')}。以下工具事件说明每一步实际发生的结果；未提交或已失效的操作不表示已执行。</p></details>${o.status==='unknown'?button('核对未知回执','query-op','button secondary full',`data-id="${id}"`):o.status==='processing'?button(o.type==='card_apply'?'查询开卡审核':'查询到账状态','settle-op','button secondary full',`data-id="${id}"`):''}`:''}<p class="help">记录的是可验证输入、规则与工具结果，不是模型内部思维过程。记录保存在当前浏览器，不跨设备同步，也不是防篡改审计服务。</p><ol class="timeline">${events.slice().reverse().map(e=>`<li><details><summary><span>${esc(e.tool)}</span>${tag(status[e.status]||e.status)}</summary><p>${esc(e.detail)}</p><small>${e.id} · V${e.version} · 业务日期 ${date(e.time)}</small></details></li>`).join('')||'<li>尚无事件。</li>'}</ol>`;}
 else if(type==='query-op'){const o=s.operations.find(o=>o.id===id);title='核对未知结果';kicker='RECEIPTS.QUERY';body=`<p class="panel-intro">${o.name} · ${o.id}。仅查询本地模拟记录，不重新提交原操作。</p><form id="query-form" data-op="${id}"><label>权威模拟记录返回<select name="result"><option value="pending">仍在处理中，保持未知</option><option value="success">确认原操作已受理 / 完成</option><option value="failed">确认原操作失败</option></select></label><button class="button primary full">查询并更新状态</button></form>`;}
 else if(type==='settle-op'){const o=s.operations.find(o=>o.id===id);title='查询赎回到账';kicker='REDEMPTION STATUS';body=`<dl class="fact-list"><div><dt>申请</dt><dd>${o.name} / ${o.id}</dd></div><div><dt>本金</dt><dd>${fmt(o.amount)}</dd></div><div><dt>最早模拟处理日期</dt><dd>${date(o.settlesAt)}</dd></div><div><dt>当前业务日期</dt><dd>${date(s.day)}</dd></div></dl>${s.day<o.settlesAt?`<div class="callout"><div><b>仍在等待处理</b><p>尚未到下一个模拟日，资金不会提前到账。</p></div></div>${button('前往模拟时钟设置','settings','button secondary full')}`:`<form id="settle-form" data-op="${id}"><label>模拟到账结果<select name="result"><option value="success">本金确认到账</option><option value="failed">到账失败，释放占用</option></select></label><button class="button primary full">查询并核对资金</button></form>`}`;}
 else if(type==='assistant'){title='说说你想安排的事。';kicker='YOUR FINANCIAL ASSISTANT';body=`<p class="panel-intro">当前仅识别有限场景，未接入大模型。输入只用于定位功能，金融条件与执行仍需你明确核实。</p><form id="assistant-form"><label>你的想法<textarea name="text" rows="4" maxlength="500" placeholder="例如：看看本月订阅扣费；比较半年内不用的资金安排" required></textarea></label><button class="button primary full">梳理下一步</button></form><div class="assistant-examples">${button('模拟转账','transfer','button secondary small')}${button('银行卡管理','cards','button secondary small')}${button('查看订阅扣费','subscriptions','button secondary small')}${button('比较理财产品','wealth','button secondary small')}</div>`;}
 else if(type==='reset'){title='刷新并保留演示？';kicker='RESET SANDBOX';body=`<p class="panel-intro">刷新后从当前浏览器恢复模拟账本、银行卡和回执，不恢复初始资金；未提交的表单输入不会保留。授权最长 24 小时，验证每笔重新进行。</p><div class="form-bottom">${button('保留当前演示','close','button secondary')}${button('确认刷新并保留','reset','button primary')}</div>`;}
 document.querySelector('#panel-kicker').textContent=kicker;document.querySelector('#panel-title').textContent=title;document.querySelector('#panel-body').innerHTML=body;document.querySelector('#panel-error').textContent='';bindForms();if(!d.open)d.showModal();d.querySelector('input:not([type=checkbox]),select,textarea,button')?.focus();}
function panelAction(fn){try{fn();}catch(e){document.querySelector('#panel-error').textContent=e.message;}}
function bindForms(){
 const form=(id,fn)=>{const el=document.querySelector('#'+id);if(el)el.onsubmit=async e=>{e.preventDefault();if(ui.busy)return;ui.busy=true;const submit=el.querySelector('button:not([data-action])');const original=submit&&submit.textContent;if(submit){submit.disabled=true;submit.textContent='正在处理本地操作…';}el.setAttribute('aria-busy','true');try{await new Promise(resolve=>requestAnimationFrame(()=>resolve()));panelAction(()=>fn(new FormData(el),el));}finally{ui.busy=false;el.removeAttribute('aria-busy');if(submit&&submit.isConnected){submit.disabled=false;submit.textContent=original;}}};};
 form('transfer-form',d=>{const o=bank.propose('transfer',String(d.get('recipient')),toMinor(d.get('amount')),{cardId:String(d.get('payer'))});ui.draw={type:'confirm',id:o.id};render();});
 form('recipient-search',d=>{ui.contactQuery=String(d.get('query')).trim();draw({type:'transfer'});});
 form('card-limit-form',(d,el)=>{const o=bank.propose('card_limit',el.dataset.card,toMinor(d.get('limit')));ui.draw={type:'confirm',id:o.id};render();});
 form('card-review-form',(d,el)=>{bank.settleCard(el.dataset.op,d.get('result'));ui.draw={type:'opdetail',id:el.dataset.op};render();});
 form('permission-form',d=>{bank.authorize({read:d.has('read'),subscriptions:d.has('subscriptions'),trade:d.has('trade'),cards:d.has('cards')});ui.draw=null;notify('本地模拟权限已更新。现在可继续对应操作，写操作仍需单独确认。');render();});
 form('settings-form',d=>{ui.mode=d.get('mode');if(d.get('profile')!==bank.state.profile)bank.setProfile(d.get('profile'));ui.draw=null;notify('沙箱设置已更新；不会发起业务。');render();});
 form('clock-form',d=>{bank.advance(Number(d.get('days')));ui.draw=null;notify('模拟日期已推进。请到任务与记录查询到期申请或到账结果。');render();});
 form('preview-form',d=>{const n=toMinor(d.get('amount')),income=toMinor(d.get('income')),expense=toMinor(d.get('expense'));if(bank.state.selected!=='NONE')bank.select(bank.state.selected,n);ui.scenarioIncome=income;ui.scenarioExpense=expense;render();});
 form('redeem-form',(d,el)=>{const o=bank.propose('redeem',el.dataset.position,toMinor(d.get('amount')));ui.draw={type:'confirm',id:o.id};render();});
 form('confirm-form',(d,el)=>{const id=el.dataset.op,o=bank.state.operations.find(o=>o.id===id);if(!d.has('confirm'))throw Error('请明确勾选确认');if(o.level==='red')bank.verify(id,String(d.get('code')));bank.execute(id,ui.mode);ui.draw=null;ui.route='tasks';ui.taskFilter='all';notify('模拟工具已返回结果，请核对任务状态与回执。');render();});
 form('query-form',(d,el)=>{bank.reconcile(el.dataset.op,d.get('result'));ui.draw={type:'opdetail',id:el.dataset.op};notify('已查询原操作回执，未重新提交。');render();});
 form('settle-form',(d,el)=>{bank.settle(el.dataset.op,d.get('result'));ui.draw={type:'opdetail',id:el.dataset.op};notify('到账状态已核对，相关资金视图同步更新。');render();});
 form('assistant-form',d=>{const result=bank.interpret(String(d.get('text')));ui.draw=null;if(['transfer','cards'].includes(result.route)){notify(result.message);open(result.route);return;}if(result.route){ui.route=result.route;if(result.route==='wealth')ui.tab='plan';if(result.route==='spending')ui.tab='bills';}notify(result.message);render();});
}
function toMinor(value){const t=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(t))throw Error('金额最多保留两位小数，不接受负数或科学计数法。');const [a,b='']=t.split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n))throw Error('金额超出范围');return n;}
function bind(){root.onclick=e=>{const b=e.target.closest('[data-action]');if(!b||!root.contains(b))return;e.preventDefault();if(!ui.draw)ui.focusReturn={action:b.dataset.action,id:b.dataset.id||''};handle(b.dataset.action,b.dataset.id);};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{ui[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;render();});const bindForm=(id,fn)=>{const f=document.querySelector('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();doAction(()=>fn(new FormData(f)));};};bindForm('transaction-search',d=>ui.search=String(d.get('query')).trim());bindForm('goal-form',d=>{bank.configure({total:toMinor(d.get('total')),need:toMinor(d.get('need')),emergency:toMinor(d.get('emergency')),months:Number(d.get('months'))});notify('资金目标已更新，旧确认已失效。');});bindForm('budget-form',d=>{bank.budget(toMinor(d.get('budget')));ui.scenarioExpense=null;notify('预算已更新，只影响未来预演，不改历史账单。');});bindForm('amount-form',d=>{const n=toMinor(d.get('amount'));if(n>bank.capacity())throw Error('配置金额超过当前可配置上限');bank.select(bank.state.selected==='NONE'?'FLEX':bank.state.selected,n);notify('配置金额已更新；产品匹配结果同步刷新。');});const panel=document.querySelector('#panel');document.querySelector('#close-panel').onclick=close;panel.oncancel=e=>{e.preventDefault();close();};panel.onclick=e=>{if(e.target!==panel)return;const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();};}
function handle(action,id){const modal=!!ui.draw;const execute=fn=>{try{fn();}catch(e){if(modal&&document.querySelector('#panel').open)document.querySelector('#panel-error').textContent=e.message;else{notify(e.message,true);render();}}};execute(()=>{
 if(action in routes){go(action,action==='wealth'?'products':action==='spending'?'bills':null);return;}
 if(action==='export-demo'){const data=bank.storageWarning?JSON.stringify({warning:bank.storageWarning,storedSnapshot:bank.exportSnapshot(),currentSnapshot:JSON.parse(bank.exportCurrent())},null,2):bank.exportCurrent();const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='banking-demo-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='transfer'||action==='cards'){if(ui.draw&&ui.draw.type==='confirm')bank.cancel(ui.draw.id);open(action);return;}
 if(action==='card-limit'){open('card-edit',id);return;}
 if(['card_lock','card_unlock','card_loss','card_apply'].includes(action)){const o=bank.propose(action,id);ui.draw={type:'confirm',id:o.id};render();return;}
 if(action==='scene-info'){open('scene-info',id);return;}
 if(['permissions','settings','profile','assistant','compare','preview','all-events'].includes(action)){if(ui.draw&&ui.draw.type==='confirm')bank.cancel(ui.draw.id);open(action);return;}
 if(action==='settle-op'&&bank.state.operations.find(o=>o.id===id)?.type==='card_apply'){open('card-review',id);return;}
 if(['txdetail','subdetail','productdetail','positiondetail','redeem','opdetail','query-op','settle-op'].includes(action)){open(action,id);return;}
 if(action==='close'){close();return;}if(action==='close-products'){go('wealth','products');return;}
 if(action==='dismiss'){ui.notice='';render();return;}
 if(action==='privacy'){ui.hidden=!ui.hidden;render();return;}
 if(action==='plan'||action==='holdings'||action==='subscriptions'){go(action==='subscriptions'?'spending':'wealth',action==='plan'?'plan':action==='holdings'?'holdings':'subscriptions');return;}
 if(action==='wealth-tab'){go('wealth',id);return;}if(action==='spending-tab'){go('spending',id);return;}
 if(action==='analyze-overview'){go('spending','bills');if(!bank.state.consent.read){open('permissions');return;}bank.analyze(ui.month);open('analysis');return;}
 if(action==='analyze'){bank.analyze(ui.month);open('analysis');return;}
 if(action==='reset-transactions'){ui.month='2026-10';ui.category='all';ui.search='';render();return;}
 if(action==='reset-products'){ui.risk='all';ui.term='all';ui.liquidity='all';ui.min='all';ui.eligible=false;render();return;}
 if(action==='keep-sub'){bank.keep(id);ui.draw=null;notify('已核实并保留订阅，没有发送取消请求。');render();return;}
 if(action==='cancel-sub'){bank.reviewSubscription(id);const o=bank.propose('subscription',id);ui.draw={type:'confirm',id:o.id};render();return;}
 if(action==='sub-receipts'){const op=bank.state.operations.slice().reverse().find(o=>o.target===id&&o.type==='subscription');if(op)open('opdetail',op.id);else{go('tasks');notify('暂无该订阅回执。');render();}return;}
 if(action==='add-compare'){if(!ui.compare.includes(id)){if(ui.compare.length>=3)throw Error('最多并列对比三项，请先移出一项。');ui.compare.push(id);}render();return;}
 if(action==='remove-compare'){ui.compare=ui.compare.filter(x=>x!==id);render();return;}
 if(action==='choose'){const current=bank.state;bank.select(id,Math.min(current.amount||bank.capacity(),bank.capacity()));ui.draw={type:'preview'};ui.route='wealth';ui.tab='products';render();return;}
 if(action==='purchase'){const o=bank.propose('purchase');ui.draw={type:'confirm',id:o.id};render();return;}
 if(action==='liquid'){bank.liquid();ui.draw=null;ui.route='wealth';ui.tab='plan';notify('已保存保留流动性的计划。未申购、未锁定资金，记录可查。');render();return;}
 if(action==='revoke'){bank.authorize({read:false,subscriptions:false,trade:false,transfer:false,cards:false});ui.draw=null;notify('本地模拟授权已撤销；待确认操作失效，已完成业务不撤回。');render();return;}
 if(action==='pause'){bank.pause();notify('已中断后续任务，待确认操作失效。');render();return;}
 if(action==='resume'){bank.resume();notify('任务已恢复；写操作需要重新确认。');render();return;}
 if(action==='unlock'){bank.unlock();ui.draw=null;notify('本地执行锁已重置，资金与历史记录保留。');render();return;}
 if(action==='cancel-op'){bank.cancel(id);notify('已取消未执行步骤。');render();return;}
 if(action==='confirm-op'){const o=bank.state.operations.find(o=>o.id===id);if(o.status!=='awaiting_confirmation')throw Error('确认已失效');open('confirm',id);return;}
 if(action==='retry-op'){const o=bank.state.operations.find(o=>o.id===id);if(o.type==='purchase'){go('wealth','products');notify('请重新核实产品与金额，再生成确认。');}else if(o.type==='subscription'){open('subdetail',o.target);}else if(o.type==='transfer')open('transfer');else if(o.type.startsWith('card_'))open('cards');else open('redeem',o.target);render();return;}
 if(action==='reset-dialog'){open('reset');return;}if(action==='reset'){location.reload();return;}
 throw Error('入口未识别，请返回总览。');
 });}
function readRoute(){const match=location.hash.match(/^#\/(overview|spending|wealth|tasks)(?:\/(products|plan|holdings|bills|subscriptions))?/);if(match){ui.route=match[1];ui.tab=match[2]||(ui.route==='wealth'?'products':'bills');}else ui.route='overview';}window.addEventListener('hashchange',()=>{if(ui.draw&&ui.draw.type==='confirm')bank.cancel(ui.draw.id);ui.draw=null;readRoute();ui.notice='';render();window.scrollTo({top:0,behavior:'instant'});});readRoute();render();
})();
